@startuml

class User {
  + UserID : int
  + Name : string
  + Email : string
  + Birthdate : date
}

class Account {
  + AccountNumber : int
  + Type : string
  + MonthlyFee : double
}

class BusinessAccount {
  + CompanyName : string
}

class PersonalAccount {}

class Page {
  + PageName : string
  + Visits : int
}

class AdvertisementPage {
  + BounceRate : float
  + ClickThroughRate : float
  + ConversionRate : float
}

User "1" -- "*" Account
BusinessAccount --|> Account
PersonalAccount --|> Account
Account "1" -- "*" Page
Page "*" -- "0..*" Page : privileges
AdvertisementPage --|> Page

@enduml

